package com.keyguard.platform.config;

import com.keyguard.platform.entity.BanEvent;
import com.keyguard.platform.entity.BanRule;
import com.keyguard.platform.entity.User;
import com.keyguard.platform.mapper.BanEventMapper;
import com.keyguard.platform.mapper.BanRuleMapper;
import com.keyguard.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Seeds first-run data after the retained schema initialization has created
 * the tables; each section is seeded only when the corresponding table is
 * empty, so restarts do not duplicate rows.
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final BanRuleMapper banRuleMapper;
    private final BanEventMapper banEventMapper;
    private final PasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           BanRuleMapper banRuleMapper,
                           BanEventMapper banEventMapper,
                           PasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.banRuleMapper = banRuleMapper;
        this.banEventMapper = banEventMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        seedUsers();
        seedBanRules();
        seedBanEvents();
    }

    private void seedUsers() {
        if (userMapper.count() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        userMapper.insert(buildUser("admin", "admin123", "ADMIN", now));
        userMapper.insert(buildUser("operator", "oper123", "USER", now));
    }

    private User buildUser(String username, String rawPassword, String role, LocalDateTime createdAt) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(createdAt);
        return user;
    }

    private void seedBanRules() {
        if (banRuleMapper.count() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        // Staggered timestamps make the default created_at ordering deterministic.
        banRuleMapper.insert(buildRule("高频访问封禁", "FREQUENCY", ">1000/min", 1000, 8,
                "ENABLED", now));
        banRuleMapper.insert(buildRule("异常地区封禁", "REGION", "BLOCKED_REGIONS", 1, 5,
                "ENABLED", now.plusSeconds(1)));
        banRuleMapper.insert(buildRule("IP黑名单", "IP", "10.0.0.0/8", 1, 10,
                "DISABLED", now.plusSeconds(2)));
    }

    private BanRule buildRule(String name, String matchType, String pattern,
                              int threshold, int priority, String status, LocalDateTime timestamp) {
        BanRule rule = new BanRule();
        rule.setName(name);
        rule.setMatchType(matchType);
        rule.setPattern(pattern);
        rule.setThreshold(threshold);
        rule.setPriority(priority);
        rule.setStatus(status);
        rule.setCreatorId(1L);
        rule.setCreatedAt(timestamp);
        rule.setUpdatedAt(timestamp);
        return rule;
    }

    private void seedBanEvents() {
        if (banEventMapper.count() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        banEventMapper.insert(buildEvent(1L, "ak-test-001", "1分钟内调用1523次", 3600,
                "203.0.113.50", now));
        banEventMapper.insert(buildEvent(2L, "ak-test-002", "来自封禁地区的访问", 86400,
                "198.51.100.1", now.plusSeconds(1)));
    }

    private BanEvent buildEvent(Long ruleId, String apiKey, String reason,
                                int duration, String sourceIp, LocalDateTime triggeredAt) {
        BanEvent event = new BanEvent();
        event.setRuleId(ruleId);
        event.setApiKey(apiKey);
        event.setReason(reason);
        event.setDuration(duration);
        event.setSourceIp(sourceIp);
        event.setTriggeredAt(triggeredAt);
        return event;
    }
}

package com.keyguard.platform.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.keyguard.platform.dto.ApiResponse;
import com.keyguard.platform.filter.JwtAuthFilter;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

import jakarta.servlet.http.HttpServletResponse;

/**
 * Security wiring: {@code /api/auth/**} is public, every other request
 * requires bearer authentication through {@link JwtAuthFilter}; stateless,
 * no CSRF requirement, JSON 401 envelope entry point.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;
    private final ObjectMapper objectMapper;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter, ObjectMapper objectMapper) {
        this.jwtAuthFilter = jwtAuthFilter;
        this.objectMapper = objectMapper;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session ->
                        session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/**").permitAll()
                        .anyRequest().authenticated())
                .exceptionHandling(exception -> exception
                        .authenticationEntryPoint((request, response, authException) -> {
                            response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                            response.setContentType("application/json;charset=UTF-8");
                            response.setCharacterEncoding("UTF-8");
                            response.getWriter().write(objectMapper.writeValueAsString(
                                    ApiResponse.error(401, "未授权访问")));
                        }))
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration authenticationConfiguration)
            throws Exception {
        return authenticationConfiguration.getAuthenticationManager();
    }

    /**
     * The filter is a {@code @Component}; keep it out of the plain servlet
     * container chain so it runs only inside the Spring Security chain.
     */
    @Bean
    public FilterRegistrationBean<JwtAuthFilter> jwtAuthFilterRegistration(JwtAuthFilter filter) {
        FilterRegistrationBean<JwtAuthFilter> registration = new FilterRegistrationBean<>(filter);
        registration.setEnabled(false);
        return registration;
    }
}

package com.keyguard.platform.controller;

import com.keyguard.platform.dto.ApiResponse;
import com.keyguard.platform.dto.LoginRequest;
import com.keyguard.platform.dto.LoginResponse;
import com.keyguard.platform.service.AuthService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * The sole public (unauthenticated) route: {@code POST /api/auth/login}.
 */
@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<LoginResponse>> login(@RequestBody LoginRequest request) {
        LoginResponse loginResponse = authService.login(request.getUsername(), request.getPassword());
        if (loginResponse == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(ApiResponse.error(401, "用户名或密码错误"));
        }
        return ResponseEntity.ok(ApiResponse.success("登录成功", loginResponse));
    }
}

